#include <algorithm>

// Given n seats (1-indexed) and m friends, return the seat number of the last friend
// under the optimal seating strategy that maximizes minimum distance to neighbors.
// Precondition: 1 <= m <= n.
int lastFriendSeat(int n, int m) {
    if (m <= 0) {
        return 0;
    }
    if (m == 1) {
        return 1;
    }
    if (m == n) {
        return n;
    }
    // For small m, friends sit in the leftmost positions.
    if (m <= (n + 1) / 2) {
        return m;
    }
    // For larger m, friends spread symmetrically from both ends.
    return n - m + 1;
}
#include <cassert>

int main() {
    assert(lastFriendSeat(1, 1) == 1);
    assert(lastFriendSeat(2, 1) == 1);
    assert(lastFriendSeat(2, 2) == 2);
    assert(lastFriendSeat(3, 1) == 1);
    assert(lastFriendSeat(3, 2) == 2);  // (n+1)/2 = 2, m=2 <=2 → return 2
    assert(lastFriendSeat(3, 3) == 3);
    assert(lastFriendSeat(4, 1) == 1);
    assert(lastFriendSeat(4, 2) == 2);  // (4+1)/2 = 2, m=2 → return 2
    assert(lastFriendSeat(4, 3) == 2);  // (5/2=2), m=3>2, return 4-3+1=2
    assert(lastFriendSeat(4, 4) == 4);
    assert(lastFriendSeat(5, 1) == 1);
    assert(lastFriendSeat(5, 2) == 2);
    assert(lastFriendSeat(5, 3) == 3);  // (5+1)/2=3, m=3 → return 3
    assert(lastFriendSeat(5, 4) == 2);  // return 5-4+1=2
    assert(lastFriendSeat(5, 5) == 5);
    assert(lastFriendSeat(10, 5) == 5); // (10+1)/2=5, m<=5 → return 5
    assert(lastFriendSeat(10, 6) == 5); // return 10-6+1=5
    assert(lastFriendSeat(10, 7) == 4);
    assert(lastFriendSeat(10, 10) == 10);
    return 0;
}
